'use strict';
// Learning content is static and shared. Only personal attempts enter the private workspace.
let lhScreen='home',lhBankId='olp',lhTopicId='',lhQuery='',lhLimit=24,lhStudyLimit=15,lhError='',lhLoadEpoch=0,lhTick,lhRetryTarget='topics';
let lhSetup={mode:'practice',count:10,minutes:30,topic:''};
const lhCache=new Map(),lhLoads=new Map();
const lhCatalog=[{id:'nw',title:'OIC NW',level:'Operational',subtitle:'Navigational watch',icon:'◈'},{id:'mlc-nw',title:'MLC NW',level:'Management',subtitle:'Deck · question practice',icon:'◈'},{id:'ew',title:'OIC EW',level:'Operational',subtitle:'Engineering watch',icon:'⚙'},{id:'mlc-ew',title:'MLC EW',level:'Management',subtitle:'Reserved · setting up',icon:'⚙',reserved:true},{id:'olp',title:'OLP exam',level:'Practice',subtitle:'Practise by module or mixed topics',icon:'▤'}];
function lhData(){const d=learningData();d.examHistory=d.examHistory||[];return d}
function lhCorrect(q){return Array.isArray(q.answers)?q.answers:Number.isInteger(q.answer)?[q.answer]:[]}
function lhMatches(t,query){const q=query.trim().toLowerCase();return !q||t.code.toLowerCase().includes(q)||q.split(/\s+/).every(w=>t.title.toLowerCase().includes(w))||/^\d+$/.test(q)&&Number(t.code)===Number(q)}
function lhTopics(bank,query=lhQuery){return bank.topics.filter(t=>lhMatches(t,query)).sort((a,b)=>{const exact=t=>t.code===query||/^\d+$/.test(query)&&Number(t.code)===Number(query);return Number(exact(b))-Number(exact(a))})}
function lhBankNow(){return lhCache.get(lhBankId)||reviewBanks.find(b=>b.id===lhBankId)}
async function lhLoadBank(id){if(lhCache.has(id))return lhCache.get(id);const current=reviewBanks.find(b=>b.id===id);if(current)return current;if(!['olp','mlc-nw'].includes(id))throw Error('This reviewer is still being prepared.');if(lhLoads.has(id))return lhLoads.get(id);const task=(async()=>{try{const r=await fetch('assets/learning/'+id+'.json',{cache:'force-cache'});if(!r.ok)throw Error('The reviewer could not load. Check your connection and retry.');const b=await r.json();if(b.id!==id||!Array.isArray(b.questions)||!Array.isArray(b.topics))throw Error('The reviewer file is incomplete. Please retry after the website update.');lhCache.set(id,b);return b}finally{lhLoads.delete(id)}})();lhLoads.set(id,task);return task}
async function lhOpenBank(id,screen){const meta=lhCatalog.find(x=>x.id===id);if(meta?.reserved)return;const epoch=++lhLoadEpoch;lhRetryTarget=screen;lhBankId=id;lhScreen='loading';lhError='';page='review';render();try{await lhLoadBank(id);if(epoch!==lhLoadEpoch||page!=='review')return;lhScreen=screen;lhQuery='';lhLimit=24;lhStudyLimit=15;render()}catch(e){if(epoch!==lhLoadEpoch||page!=='review')return;lhError=e.message;lhScreen='error';render()}}
function lhGo(screen){lhLoadEpoch++;lhScreen=screen;if(screen!=='topics')lhQuery='';lhLimit=24;page='review';reviewReadSet=null;render();window.scrollTo(0,0)}
function lhHead(title,back='home',sub=''){return `<header class="learning-heading"><div><button class="text-button" data-lh="${back}">← ${back==='home'?'Learning':back==='exams'?'Exams':'Study'}</button><h1>${esc(title)}</h1>${sub?`<p class="hint">${esc(sub)}</p>`:''}</div></header>`}
function lhHome(){app.innerHTML=`<header class="hub-task-heading"><h1>Learning</h1><p>Choose how you want to learn.</p></header><div class="lh-choice-grid"><button class="card lh-choice" data-lh="study"><span class="lh-symbol">${journalIcon('words')}</span><h2>Study</h2><p>Find an OLP topic. Read the questions with their source-marked answers.</p><b>Open Study →</b></button><button class="card lh-choice" data-lh="exams"><span class="lh-symbol">${journalIcon('review')}</span><h2>Exams</h2><p>Quick practice or a timed mock. Pick your level and reviewer.</p><b>Open Exams →</b></button></div>${lhResumeCards()}`}
function lhResumeCards(){const m=lhData().examSession,old=state.review.session,legacy=learningData().mockSession;return `${m&&!m.done?`<button class="card lh-resume" data-lh="resume"><strong>Continue ${m.mode==='mock'?'mock exam':'practice'}</strong><span>${esc(lhCatalog.find(x=>x.id===m.bankId)?.title||m.bankId)} · ${Object.keys(m.answers).length}/${m.ids.length} answered →</span></button>`:''}${old&&!old.done?'<button class="text-button" data-lh="legacy">Continue earlier review round →</button>':''}${legacy&&!legacy.done?'<button class="text-button" data-learning="mock">Continue earlier mock exam →</button>':''}`}
function lhStudyLanding(){app.innerHTML=lhHead('Study')+`<button class="card lh-choice" data-lh-study="olp"><span class="lh-symbol">▤</span><h2>OLP questions & answers</h2><p>Original module numbers and topic titles.</p><b>Choose a topic →</b></button><p class="hint">Source: supplied 2018 answer compilation. Source markings are not a guarantee of current rules or correctness.</p>`}
function lhTopicCards(bank,exam=false){const topics=lhTopics(bank),chosen=exam?lhSetup.topic:lhTopicId;return `<p class="hint" role="status">${topics.length} matching modules</p><div class="lh-topic-grid">${topics.slice(0,lhLimit).map(t=>`<button class="card lh-topic ${chosen===t.id?'selected':''}" data-lh-${exam?'pool':'topic'}="${esc(t.id)}"><span class="lh-module-code">${esc(t.code)}</span><strong>${esc(t.title)}</strong><small>${t.count?`${t.count} questions`:'Source module · no question set'}</small></button>`).join('')||'<p>No matching module. Try its number or a word from its title.</p>'}</div>${topics.length>lhLimit?'<button class="text-button" data-lh="moreTopics">Show more topics ↓</button>':''}`}
function lhSearchInput(){return `<label class="search">${icon('search')}<input id="lhTopicSearch" type="search" placeholder="Topic or module number · e.g. 0001" aria-label="Search OLP by topic title or module number" value="${esc(lhQuery)}"></label>`}
function lhWireSearch(exam=false){const el=document.querySelector('#lhTopicSearch');if(!el)return;el.oninput=e=>{lhQuery=e.target.value;lhLimit=24;const cards=document.querySelector('#lhTopicCards');if(cards)cards.innerHTML=lhTopicCards(lhBankNow(),exam);const current=hubRouteHistory.at(-1);if(current?.page==='review'&&current.learningHub){current.learningHub.query=lhQuery;current.learningHub.limit=lhLimit}}}
function lhStudyTopics(){const bank=lhBankNow();app.innerHTML=lhHead('OLP topics','study')+lhSearchInput()+`<div id="lhTopicCards">${lhTopicCards(bank)}</div>`;lhWireSearch()}
function lhSource(q,bank){const path=bank.sourcePdf||'assets/review/'+bank.id+'.pdf';return `<a class="review-source" href="${esc(path)}#page=${q?.page||1}" target="_blank" rel="noopener">Source PDF · page ${q?.page||1} ↗</a>`}
function lhStudyTopic(){const bank=lhBankNow(),topic=bank.topics.find(t=>t.id===lhTopicId);if(!topic){lhStudyTopics();return}const qs=bank.questions.filter(q=>q.topicId===topic.id);app.innerHTML=lhHead(topic.title,'topics','OLP '+topic.code)+`<p class="lh-source-note">Answers below follow the supplied 2018 compilation. Check current approved references when studying procedures or rules.</p>${qs.slice(0,lhStudyLimit).map(q=>{const key=lhCorrect(q);return `<article class="card lh-study-answer"><small>Q${q.number}</small><h2>${esc(q.question)}</h2>${key.length?`<div class="lh-direct-answer"><strong>${key.length>1?'Source-marked answers':'Source-marked answer'}</strong>${key.map(i=>`<p>✓ ${esc(q.options[i])}</p>`).join('')}</div>`:'<p class="hint">No clear answer marking in this source. An answer has not been guessed.</p>'}${q.keyWarning?'<p class="hint">The source markings do not match the requested number of answers. Verify this item in the PDF.</p>':''}${q.needsFigure?'<p class="hint">Use the source page for the illustration or visual context.</p>':''}<details><summary>All source choices</summary><ol>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol></details>${lhSource(q,bank)}</article>`}).join('')||`<section class="card"><h2>This module has no question set.</h2><p>The source contains a completion declaration or other module text.</p>${lhSource(topic,bank)}</section>`}${qs.length>lhStudyLimit?'<button class="btn quiet" data-lh="moreStudy">Read more questions ↓</button>':''}<button class="text-button" data-lh-topic-exam="${esc(topic.id)}" ${qs.some(q=>lhCorrect(q).length&&!q.needsFigure)?'':'disabled'}>Practise this topic in exam form →</button>`}
function lhExams(){app.innerHTML=lhHead('Exams')+lhResumeCards()+`<div class="lh-exam-grid">${lhCatalog.map(b=>`<button class="card lh-exam-card" data-lh-bank="${b.id}" ${b.reserved?'disabled':''}><span class="lh-level">${b.level}</span><h2><span aria-hidden="true">${b.icon}</span> ${b.title}</h2><p>${b.subtitle}</p><small>${b.reserved?'Reserved as requested':b.id==='mlc-nw'?'Available · unscored; answer key needed':'Practice & timed mock →'}</small></button>`).join('')}</div>`}
function lhSetupView(){const bank=lhBankNow(),meta=lhCatalog.find(b=>b.id===lhBankId),olp=bank.id==='olp';const topic=olp?bank.topics.find(t=>t.id===lhSetup.topic):null;app.innerHTML=lhHead(meta.title,'exams',meta.level+' · '+meta.subtitle)+`<section class="card lh-exam-setup"><div class="lh-mode-switch" role="group" aria-label="Exam mode"><button data-lh-mode="practice" aria-pressed="${lhSetup.mode==='practice'}" class="${lhSetup.mode==='practice'?'selected':''}">Quick practice</button><button data-lh-mode="mock" aria-pressed="${lhSetup.mode==='mock'}" class="${lhSetup.mode==='mock'?'selected':''}">Timed mock</button></div><p class="hint">${lhSetup.mode==='practice'?'Check answers as you practise.':'Results appear after submission or when time runs out.'}</p>${bank.id==='mlc-nw'?'<p class="lh-source-note"><strong>No answer key in the uploaded file.</strong> You can rehearse the questions, but correctness and a numerical score are unavailable.</p>':''}${olp?`<label class="field">Question pool<select id="lhPool"><option value="">Mixed modules</option>${bank.topics.filter(t=>t.count).map(t=>`<option value="${esc(t.id)}" ${lhSetup.topic===t.id?'selected':''}>${esc(t.code)} · ${esc(t.title)}</option>`).join('')}</select></label>${topic?`<p class="hint">Selected: ${esc(topic.code)} · ${esc(topic.title)}</p>`:''}`:`<label class="field">Question pool<select id="lhPool"><option value="">Mixed questions</option>${reviewSets(bank).map(set=>`<option value="${set.set}" ${String(lhSetup.topic)===String(set.set)?'selected':''}>Source set ${set.set} · Q${set.questions[0].number}–${set.questions.at(-1).number}</option>`).join('')}</select></label>`}<div class="lh-setup-fields"><label class="field">Questions<select id="lhCount">${[10,20,40].map(n=>`<option ${n===lhSetup.count?'selected':''}>${n}</option>`).join('')}</select></label>${lhSetup.mode==='mock'?`<label class="field">Time limit<select id="lhMinutes">${[15,30,60].map(n=>`<option value="${n}" ${n===lhSetup.minutes?'selected':''}>${n} minutes</option>`).join('')}</select></label>`:''}</div><p id="lhStartStatus" role="status" class="hint"></p><button class="btn" data-lh="start">Start ${lhSetup.mode==='mock'?'mock exam':'practice'} →</button><p class="hint">Source questions; no official exam claim. Diagram-dependent items are excluded from scored practice.</p></section>${olp?`<details class="card lh-exam-topic-search"><summary>Find a module by title or number</summary>${lhSearchInput()}<div id="lhTopicCards">${lhTopicCards(bank,true)}</div></details>`:''}`;document.querySelector('#lhPool').onchange=e=>{lhSetup.topic=e.target.value};document.querySelector('#lhCount').onchange=e=>{lhSetup.count=Number(e.target.value)};const minutes=document.querySelector('#lhMinutes');if(minutes)minutes.onchange=e=>{lhSetup.minutes=Number(e.target.value)};lhWireSearch(true)}
function lhExamPool(){const bank=lhBankNow();return bank.questions.filter(q=>(!lhSetup.topic||(bank.id==='olp'?q.topicId===lhSetup.topic:String(q.set)===String(lhSetup.topic)))&&!state.review.flagged.includes(q.id)&&!q.needsFigure&&!q.keyWarning&&(bank.id==='mlc-nw'||lhCorrect(q).length))}
function lhShuffle(list){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function lhStart(){const pool=lhExamPool().slice();if(!pool.length){document.querySelector('#lhStartStatus').textContent='No eligible questions in this selection. Choose another module or set.';return false}for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}const m={bankId:lhBankId,mode:lhSetup.mode,ids:pool.slice(0,lhSetup.count).map(q=>q.id),optionOrder:Object.fromEntries(pool.slice(0,lhSetup.count).map(q=>[q.id,lhShuffle(q.options.map((_,i)=>i))])),answers:{},checked:{},index:0,done:false,deadline:lhSetup.mode==='mock'?Date.now()+lhSetup.minutes*60000:null};if(!learningSave(d=>{d.examSession=m})){document.querySelector('#lhStartStatus').textContent=learningMessage;return false}lhScreen='round';render();return true}
function lhQuestion(m=lhData().examSession){return lhBankNow()?.questions.find(q=>q.id===m?.ids[m.index])}
function lhIsCorrect(q,selected=[]){const expected=lhCorrect(q);return expected.length>0&&expected.length===selected.length&&expected.every(i=>selected.includes(i))}
function lhChoose(choice){const m=lhData().examSession,q=lhQuestion(m);if(!m||m.done||!q||!Number.isInteger(choice)||choice<0||choice>=q.options.length||m.checked[q.id])return false;if(m.deadline&&Date.now()>=m.deadline)return lhFinish();const multi=lhCorrect(q).length>1;const ok=learningSave(()=>{const a=m.answers[q.id]||[];m.answers[q.id]=multi?(a.includes(choice)?a.filter(i=>i!==choice):[...a,choice]):[choice];if(m.mode==='practice'&&!multi)m.checked[q.id]=true});if(ok)render();return ok}
function lhCheck(){const m=lhData().examSession,q=lhQuestion(m);if(!m||m.done||!q||!m.answers[q.id]?.length)return false;const ok=learningSave(()=>{m.checked[q.id]=true});if(ok)render();return ok}
function lhMove(delta){const m=lhData().examSession;if(!m||m.done)return;if(m.deadline&&Date.now()>=m.deadline){lhFinish();return}m.index=Math.max(0,Math.min(m.ids.length-1,m.index+delta));render()}
function lhFinish(){const m=lhData().examSession,bank=lhBankNow();if(!m||m.done||bank?.id!==m.bankId)return false;const before=JSON.stringify(state.review),qs=m.ids.map(id=>bank.questions.find(q=>q.id===id)),keyed=qs.filter(q=>lhCorrect(q).length),score=keyed.reduce((sum,q)=>sum+Number(lhIsCorrect(q,m.answers[q.id])),0);const ok=learningSave(d=>{m.done=true;m.score=keyed.length?score:null;m.keyedTotal=keyed.length;const record={track:bank.id,kind:m.mode,score:m.score,total:m.ids.length,date:new Date().toISOString()};if(keyed.length===qs.length){state.review.history.unshift(record);state.review.history=state.review.history.slice(0,30);for(const q of qs)if(m.answers[q.id]?.length){const old=state.review.records[q.id];state.review.records[q.id]={attempts:(old?.attempts||0)+1,correct:lhIsCorrect(q,m.answers[q.id])}}}else{d.examHistory.unshift(record);d.examHistory=d.examHistory.slice(0,20)}});if(!ok){state.review=JSON.parse(before);const status=document.querySelector('#lhExamStatus');if(status)status.textContent=learningMessage;return false}clearTimeout(lhTick);render();return true}
function lhRound(){clearTimeout(lhTick);const m=lhData().examSession,bank=lhBankNow();if(!m||bank?.id!==m.bankId){lhExams();return}if(m.done){lhResult();return}const expired=m.deadline&&Date.now()>=m.deadline;if(expired&&lhFinish())return;const q=lhQuestion(m);if(!q){lhExams();return}const selected=m.answers[q.id]||[],key=lhCorrect(q),checked=!!m.checked[q.id],show=m.mode==='practice'&&checked;app.innerHTML=lhHead(lhCatalog.find(b=>b.id===bank.id)?.title||bank.title,'exams')+`<div class="review-round-meta"><strong>${m.mode==='mock'?'Mock exam':'Practice'} · ${m.index+1}/${m.ids.length}</strong>${m.deadline?'<time id="lhClock"></time>':'<span>No time limit</span>'}</div><progress value="${Object.keys(m.answers).length}" max="${m.ids.length}" aria-label="Questions answered"></progress><article class="card review-question"><small>Q${q.number}${key.length>1?` · choose ${key.length}`:''}</small><h1>${esc(q.question)}</h1><div class="review-options">${(m.optionOrder?.[q.id]||q.options.map((_,i)=>i)).map((i,slot)=>`<button class="review-option ${selected.includes(i)?'selected':''} ${show&&key.includes(i)?'correct':''} ${show&&key.length&&selected.includes(i)&&!key.includes(i)?'incorrect':''}" data-lh-choice="${i}" aria-pressed="${selected.includes(i)}" ${checked?'disabled':''}><b>${String.fromCharCode(65+slot)}</b><span>${esc(q.options[i])}</span></button>`).join('')}</div>${show?(key.length?`<div class="review-feedback"><strong>${lhIsCorrect(q,selected)?'Correct':'Not correct'} · source key</strong>${key.map(i=>`<p>${esc(q.options[i])}</p>`).join('')}</div>`:'<p class="hint">Answer recorded. This source has no marked key; correctness is not scored.</p>'):m.mode==='practice'&&key.length>1?'<button class="btn" data-lh="check">Check selected answers</button>':''}${m.mode==='practice'?lhSource(q,bank):''}<p id="lhExamStatus" class="hint" role="status">${esc(learningMessage)}</p></article><div class="review-pagination"><button class="btn quiet" data-lh="previous" ${m.index?'':'disabled'}>← Previous</button><button class="btn" data-lh="next" ${m.index===m.ids.length-1?'disabled':''}>Next →</button></div><button class="text-button" data-lh="finish">${m.mode==='mock'?'Submit exam':'Finish practice'} · ${Object.keys(m.answers).length}/${m.ids.length} answered</button>`;if(m.deadline&&!expired){const owner=cloudUser?.id||'local';const tick=()=>{if(page!=='review'||lhScreen!=='round'||m!==lhData().examSession||m.done||(cloudUser?.id||'local')!==owner)return;const left=Math.max(0,Math.ceil((m.deadline-Date.now())/1000));const clock=document.querySelector('#lhClock');if(clock)clock.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(!left){lhFinish();return}lhTick=setTimeout(tick,1000)};tick()}}
function lhResult(){const m=lhData().examSession,bank=lhBankNow();app.innerHTML=lhHead('Your result','exams')+`<section class="card"><h2>${m.score===null?'Practice completed':m.score+' / '+m.keyedTotal}</h2><p>${m.score===null?'Unscored · the source has no marked answer key.':'Source-marked score · recorded in Progress'}</p><button class="btn" data-nav="progress">View Progress →</button></section>${m.ids.map(id=>{const q=bank.questions.find(q=>q.id===id),key=lhCorrect(q),selected=m.answers[id]||[];return `<details class="card lh-result"><summary>Q${q.number} · ${esc(q.question)}</summary><p>Your answer: ${selected.length?selected.map(i=>esc(q.options[i])).join('; '):'Unanswered'}</p>${key.length?`<p><strong>Source answer: ${key.map(i=>esc(q.options[i])).join('; ')}</strong></p>`:'<p>No answer key available.</p>'}${lhSource(q,bank)}</details>`}).join('')}`}
const lhOldReviewView=reviewView,lhOldNav=nav,lhOldRender=render,lhOldRenderNav=renderNav,lhOldToday=learningToday,lhOldProgress=learningProgress;
reviewView=function(){if(reviewReadSet!==null&&reviewBank()){reviewReaderView();return}if(lhScreen==='home')lhHome();else if(lhScreen==='study')lhStudyLanding();else if(lhScreen==='topics')lhStudyTopics();else if(lhScreen==='topic')lhStudyTopic();else if(lhScreen==='exams')lhExams();else if(lhScreen==='setup')lhSetupView();else if(lhScreen==='round')lhRound();else if(lhScreen==='legacy'){if(reviewScreen==='round'&&state.review.session)reviewQuestionView();else lhExams()}else if(lhScreen==='loading')app.innerHTML=lhHead('Opening reviewer…')+'<p role="status">Loading the study file. Your progress stays safe.</p>';else app.innerHTML=lhHead('Couldn’t open this file')+`<section class="card"><p>${esc(lhError)}</p><button class="btn" data-lh="retry">Retry loading</button></section>`};
nav=function(p){if(p==='review'){lhLoadEpoch++;lhScreen='home';reviewReadSet=null;lhQuery=''}return lhOldNav(p)};
renderNav=function(){lhOldRenderNav();for(const id of ['desktopNav','mobileNav']){const label=document.getElementById(id)?.querySelector('[data-nav="review"] span');if(label)label.textContent='Learning'}};
render=function(){lhOldRender();if(page==='review'&&state.hubOnboardingCompleted&&(!cloudEnabled||cloudReady))document.querySelector('#sectionName').textContent='Learning'};
learningToday=function(){lhOldToday();app.innerHTML=app.innerHTML.replace('data-learning="review"','data-lh="home"').replace('Start a review','Explore Learning').replace('Continue review','Continue learning')};
learningProgress=function(){lhOldProgress();const h=state.review.history.filter(x=>['olp','mlc-nw'].includes(x.track)),u=lhData().examHistory;app.insertAdjacentHTML('beforeend',`<section class="card"><h2>Learning exams</h2>${h.slice(0,5).map(x=>`<p><strong>${x.score}/${x.total}</strong> · ${esc(x.track.toUpperCase())} · ${new Date(x.date).toLocaleDateString()}</p>`).join('')||'<p class="hint">Complete a scored exam to see its result here.</p>'}${u.slice(0,3).map(x=>`<p>${esc(x.track.toUpperCase())} · unscored practice · ${x.total} questions</p>`).join('')}</section>`)};
const lhScreenNames=[['review','Learning','Study Exams OLP topics modules mock Operational Management']];const dest=hubDestinations.findIndex(d=>d[0]==='review');if(dest>=0)hubDestinations[dest]=lhScreenNames[0];
hubQuickGuides.home=['Today',['Start a private journal entry.','Open Learning for Study or Exams.']];
hubQuickGuides.review=['Learning',['Choose Study for OLP questions with direct source-marked answers.','Search OLP topics by their title or module number.','Exams offers operational, management and OLP practice.','Quick practice gives feedback; timed mocks show results after submission.','MLC NW is unscored until an answer key is supplied. MLC EW is reserved.']];
let lhOwner=cloudUser?.id||'local';const lhBeforeOwnerRender=render;render=function(){const owner=cloudUser?.id||'local';if(owner!==lhOwner){lhOwner=owner;lhScreen='home';lhLoadEpoch++;clearTimeout(lhTick);lhQuery='';lhTopicId=''}lhBeforeOwnerRender()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(!Object.keys(d).some(k=>k.startsWith('lh')))return;e.stopImmediatePropagation();if(d.lhStudy){lhOpenBank(d.lhStudy,'topics');return}if(d.lhBank){lhSetup={mode:'practice',count:10,minutes:30,topic:''};lhOpenBank(d.lhBank,'setup');return}if(d.lhTopic){lhTopicId=d.lhTopic;lhStudyLimit=15;lhScreen='topic';render();window.scrollTo(0,0);return}if(d.lhTopicExam){lhSetup={mode:'practice',count:10,minutes:30,topic:d.lhTopicExam};lhScreen='setup';render();return}if(d.lhPool){lhSetup.topic=d.lhPool;lhSetupView();return}if(d.lhMode){lhSetup.mode=d.lhMode;lhSetupView();return}if(d.lhChoice!==undefined){lhChoose(Number(d.lhChoice));return}switch(d.lh){case'home':case'study':case'topics':case'exams':lhGo(d.lh);return;case'moreTopics':lhLimit+=24;if(lhScreen==='setup')document.querySelector('#lhTopicCards').innerHTML=lhTopicCards(lhBankNow(),true);else document.querySelector('#lhTopicCards').innerHTML=lhTopicCards(lhBankNow());return;case'moreStudy':lhStudyLimit+=15;render();return;case'start':lhStart();return;case'check':lhCheck();return;case'next':lhMove(1);return;case'previous':lhMove(-1);return;case'finish':lhFinish();return;case'resume':{const m=lhData().examSession;if(m)lhOpenBank(m.bankId,'round');return}case'legacy':lhScreen='legacy';reviewScreen='round';state.review.track=state.review.session.track;reviewReadSet=null;page='review';render();return;case'retry':lhOpenBank(lhBankId,lhRetryTarget);return}},true);
const lhOldHelp=helpUI;helpUI=function(){lhOldHelp();app.innerHTML=app.innerHTML.replace('Start a review from Today.','Open Learning from Today or the dock. Choose Study for direct answers or Exams for practice.').replace('review round','practice round')};
const lhOldSnapshot=hubRouteSnapshot,lhOldRouteKey=hubRouteKey,lhOldBack=hubBack;
hubRouteSnapshot=function(){return {...lhOldSnapshot(),learningHub:{screen:lhScreen,bankId:lhBankId,topic:lhTopicId,query:lhQuery,limit:lhLimit,studyLimit:lhStudyLimit}}};
hubRouteKey=function(r){return lhOldRouteKey(r)+(r.page==='review'?JSON.stringify(r.learningHub):'')};
hubBack=function(){const prev=hubRouteHistory.at(-2)?.learningHub;if(prev){lhLoadEpoch++;lhScreen=prev.screen;lhBankId=prev.bankId;lhTopicId=prev.topic;lhQuery=prev.query;lhLimit=prev.limit;lhStudyLimit=prev.studyLimit}return lhOldBack()};
const lhOldRecordRoute=hubRecordRoute;hubRecordRoute=function(){if(page==='review'&&lhScreen==='loading')return;lhOldRecordRoute()};
const lhOldGettingStarted=gettingStartedView;gettingStartedView=function(){lhOldGettingStarted();for(const node of app.querySelectorAll('strong'))if(node.textContent==='Review')node.textContent='Learning'};
render();
